# Final SD card fix: Write userconf.txt to enable pi user + SSH on Pi OS Bookworm
# Run with SD card inserted

$bootDrive = Get-PSDrive -PSProvider FileSystem | Where-Object {
    $_.Name -ne "C" -and (Test-Path "$($_.Root)cmdline.txt")
} | Select-Object -First 1

if (-not $bootDrive) {
    Write-Host "ERROR: SD card not found." -ForegroundColor Red
    exit 1
}

$boot = $bootDrive.Root
Write-Host "Found SD card at: $boot" -ForegroundColor Green

# SHA-512 crypt hash of 'spikefed123' (generated by passlib)
$userconf = "pi:`$6`$SpikeFedSalt01`$vQ6vIG4OkNaXIw3cghATjimrNg2YWidwraVSJv9JTBKp/1.cDR10iRLr.LO9UUEqlZmHbBZa3nwbV0cZ8N9iw0"
[System.IO.File]::WriteAllText("${boot}userconf.txt", $userconf)
Write-Host "userconf.txt written  (pi / spikefed123)" -ForegroundColor Green

# Ensure SSH file exists
if (-not (Test-Path "${boot}ssh")) {
    [System.IO.File]::WriteAllText("${boot}ssh", "")
}
Write-Host "SSH enable file: OK" -ForegroundColor Green

# Show cmdline
Write-Host "cmdline.txt:" -ForegroundColor Cyan
Get-Content "${boot}cmdline.txt"

Write-Host ""
Write-Host "=== Done! Eject SD, put in Pi, power on, wait 90s ===" -ForegroundColor Green
